FROM (SELECT COUNT(*) AS cnt FROM molecule WHERE label = '+') AS total,
     (SELECT COUNT(DISTINCT molecule_id) AS cnt FROM atom WHERE element = 'f' AND molecule_id IN (SELECT molecule_id FROM molecule WHERE label = '+')) AS has_f;

